import os
import sys
import json
import argparse
import math
import shutil

def format_size(size, fmt, unit='bytes'):
    if fmt == 'plain' or unit == 'blocks':
        return str(size)
    base = 1000 if fmt == 'metric' else 1024
    suffixes = ['', 'K', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y']
    if size < base: return str(size)
    exponent = int(math.log(size, base))
    if exponent >= len(suffixes): exponent = len(suffixes) - 1
    val = size / (base ** exponent)
    return f"{val:.1f}{suffixes[exponent]}"

class Node:
    def __init__(self, name, size, is_dir=False):
        self.name, self.size, self.is_dir, self.children, self.parent, self.depth = name, size, is_dir, [], None, 0

def build_tree(paths, quantity, dedupe_hardlinks):
    shared_inodes = {}
    def get_info(path):
        try:
            st = os.lstat(path)
            if quantity == 'apparent-size': s = st.st_size
            elif quantity == 'block-count': s = st.st_blocks
            else: s = st.st_blocks * 512
            return s, st.st_dev, st.st_ino, os.path.isdir(path) and not os.path.islink(path), st.st_nlink
        except OSError: return 0, 0, 0, False, 0
    def scan(path, depth):
        size, dev, ino, is_dir, nlink = get_info(path)
        node = Node(os.path.basename(path.rstrip('/')) or path, size, is_dir)
        node.depth = depth
        if nlink > 1:
            if (dev, ino) not in shared_inodes: shared_inodes[(dev, ino)] = []
            shared_inodes[(dev, ino)].append(path)
        if is_dir:
            try:
                with os.scandir(path) as it:
                    for entry in it:
                        child = scan(entry.path, depth + 1); child.parent = node; node.children.append(child)
            except OSError: pass
            total = node.size
            if dedupe_hardlinks:
                seen = {}
                for child in node.children:
                    c_path = os.path.join(path, child.name); _, c_dev, c_ino, c_is_dir, c_nlink = get_info(c_path)
                    if c_nlink > 1 and not c_is_dir:
                        if (c_dev, c_ino) in seen: continue
                        seen[(c_dev, c_ino)] = True
                    total += child.size
            else:
                for child in node.children: total += child.size
            node.size = total
        return node
    roots = [scan(p, 0) for p in paths]
    if len(roots) > 1:
        root = Node("(total)", sum(r.size for r in roots), True)
        for r in roots: r.parent = root; r.depth = 1; root.children.append(r)
        stack = [(root, 0)]
        while stack:
            n, d = stack.pop(); n.depth = d
            for c in n.children: stack.append((c, d + 1))
        return root, shared_inodes
    return roots[0], shared_inodes

def json_to_node(data):
    node = Node(data["name"], data["size"], data["children"] != [])
    for c_data in data["children"]:
        child = json_to_node(c_data); child.parent = node; node.children.append(child)
    stack = [(node, 0)]
    while stack:
        n, d = stack.pop(); n.depth = d
        for c in n.children: stack.append((c, d + 1))
    return node

def filter_and_sort(node, max_depth, min_ratio, total_root_size, no_sort):
    if node.depth >= max_depth: node.children = []; return
    new_children = []
    for c in node.children:
        if total_root_size > 0 and (c.size / total_root_size) < min_ratio: continue
        filter_and_sort(c, max_depth, min_ratio, total_root_size, no_sort)
        new_children.append(c)
    if not no_sort: new_children.sort(key=lambda x: (-x.size, x.name))
    node.children = new_children

def get_tree_lines(node, prefixes, is_last):
    if node.parent is None: conn = "└─┬" if node.children else "└──"
    else: conn = ("└" if is_last else "├") + ("─┬" if node.children else "──")
    line = {'size': node.size, 'name': node.name, 'conn': conn, 'prefix': "".join(prefixes), 'depth': node.depth, 'ancestors': []}
    curr = node.parent
    while curr: line['ancestors'].append(curr.size); curr = curr.parent
    line['ancestors'].reverse()
    res = [line]
    for i, c in enumerate(node.children):
        new_prefixes = prefixes + ("  ",) if is_last else prefixes + ("│ ",)
        res.extend(get_tree_lines(c, new_prefixes, i == len(node.children) - 1))
    return res

def main():
    parser = argparse.ArgumentParser(); parser.add_argument("FILES", nargs="*", default=["."])
    parser.add_argument("-V", "--version", action="version", version="pdu 0.21.1")
    parser.add_argument("--json-input", action="store_true"); parser.add_argument("--json-output", action="store_true")
    parser.add_argument("-b", "--bytes-format", choices=["plain", "metric", "binary"], default="metric")
    parser.add_argument("-H", "--deduplicate-hardlinks", "--detect-links", "--dedupe-links", action="store_true")
    parser.add_argument("--top-down", action="store_true"); parser.add_argument("-q", "--quantity", choices=["apparent-size", "block-size", "block-count"], default="block-size")
    parser.add_argument("-d", "--max-depth", default="10"); parser.add_argument("-w", "--total-width", type=int)
    parser.add_argument("--column-width", nargs=2, type=int); parser.add_argument("-m", "--min-ratio", type=float, default=0.01)
    parser.add_argument("--no-sort", action="store_true"); parser.add_argument("-s", "--silent-errors", action="store_true")
    parser.add_argument("-p", "--progress", action="store_true"); parser.add_argument("--threads", default="auto")
    parser.add_argument("--omit-json-shared-details", action="store_true"); parser.add_argument("--omit-json-shared-summary", action="store_true")
    args, _ = parser.parse_known_args()
    max_depth = float('inf') if args.max_depth == 'inf' else int(args.max_depth)
    if args.json_input:
        data = json.load(sys.stdin); root = json_to_node(data["tree"]); shared_inodes = {}
    else:
        root, shared_inodes = build_tree(args.FILES, args.quantity, args.deduplicate_hardlinks)
    filter_and_sort(root, max_depth, args.min_ratio, root.size, args.no_sort)
    if args.json_output:
        def n2d(n): return {"name": n.name, "size": n.size, "children": [n2d(c) for c in n.children]}
        out = {"schema-version": "2024-11-02", "pdu": "0.21.1", "unit": "blocks" if args.quantity == "block-count" else "bytes", "tree": n2d(root)}
        if args.deduplicate_hardlinks:
            details = []; total_s, all_l, det_l, excl_l, excl_i, excl_s = 0, 0, 0, 0, 0, 0
            for (dev, ino), paths in shared_inodes.items():
                st = os.stat(paths[0]); s = st.st_size; nlink = st.st_nlink
                details.append({"ino": ino, "size": s, "links": nlink, "paths": paths})
                total_s += s; all_l += nlink; det_l += len(paths)
                if nlink == len(paths): excl_i += 1; excl_l += nlink; excl_s += s
            out["shared"] = {"details": details, "summary": {"inodes": len(shared_inodes), "exclusive_inodes": excl_i, "all_links": all_l, "detected_links": det_l, "exclusive_links": excl_l, "shared_size": total_s, "exclusive_shared_size": excl_s}}
        print("\n\n" + json.dumps(out, separators=(',', ':'))); return
    lines = get_tree_lines(root, (), True)
    if not args.top_down:
        lines.reverse()
        for line in lines: line['conn'] = line['conn'].replace('└', '┌').replace('┬', '┴')
    fmt_unit = "blocks" if args.quantity == "block-count" else "bytes"
    formatted_sizes = [format_size(line['size'], args.bytes_format, fmt_unit) for line in lines]
    max_size_len = max(len(s) for s in formatted_sizes) if formatted_sizes else 0
    total_width = args.total_width or shutil.get_terminal_size((100, 24)).columns
    if args.column_width: tree_width, bar_width = args.column_width
    else:
        max_tree_len = max(len(line['prefix'] + line['conn'] + line['name']) for line in lines) if lines else 0
        tree_width = max_tree_len + 1
        bar_width = max(10, total_width - max_size_len - 4 - tree_width - 1 - 2 - 1 - 4)
    print("\n")
    for i, line in enumerate(lines):
        ratio = line['size'] / root.size if root.size > 0 else 0
        def get_l(sz): return int(round((sz / root.size) * bar_width)) if root.size > 0 else 0
        d, anc, l_self = line['depth'], line['ancestors'] + [line['size']], get_l(line['size'])
        l1, l2, l3 = get_l(anc[1]) if len(anc) > 1 else l_self, get_l(anc[2]) if len(anc) > 2 else (get_l(anc[1]) if len(anc) > 1 else l_self), get_l(anc[3]) if len(anc) > 3 else (get_l(anc[2]) if len(anc) > 2 else (get_l(anc[1]) if len(anc) > 1 else l_self))
        bar = [' '] * bar_width
        if d >= 1:
            for j in range(get_l(anc[1])): bar[j] = '░'
        if d >= 2:
            for j in range(get_l(anc[2])): bar[j] = '▒'
        if d >= 3:
            for j in range(get_l(anc[3])): bar[j] = '▓'
        for j in range(l_self): bar[j] = '█'
        size_str = formatted_sizes[i].rjust(max_size_len)
        tree_part = (line['prefix'] + line['conn'] + line['name']).ljust(tree_width)
        if len(tree_part) > tree_width: tree_part = tree_part[:tree_width-3] + "..."
        print(f"{size_str}    {tree_part} │{''.join(bar)}│{f'{int(round(ratio*100))}%':>4}")
    if args.deduplicate_hardlinks and shared_inodes:
        excl_i = [ino for ino, paths in shared_inodes.items() if os.stat(paths[0]).st_nlink == len(paths)]
        if len(excl_i) == len(shared_inodes):
            print("Hardlinks detected! No files have links outside this tree")
            print(f"* Number of shared inodes: {len(shared_inodes)}")
            all_l = sum(os.stat(p[0]).st_nlink for p in shared_inodes.values())
            print(f"* Total number of links: {all_l}")
            total_s = sum(os.stat(p[0]).st_size for p in shared_inodes.values())
            print(f"* Total shared size: {total_s}   ")
        elif not excl_i:
            print("Hardlinks detected! All hardlinks within this tree have links without")
            print(f"* Number of shared inodes: {len(shared_inodes)}")
            all_l = sum(os.stat(p[0]).st_nlink for p in shared_inodes.values())
            det_l = sum(len(p) for p in shared_inodes.values())
            print(f"* Total number of links: {all_l} total, {det_l} detected")
            total_s = sum(os.stat(p[0]).st_size for p in shared_inodes.values())
            print(f"* Total shared size: {total_s}   ")
        else:
            print("Hardlinks detected! Some files have links outside this tree")
            print(f"* Number of shared inodes: {len(shared_inodes)} total, {len(excl_i)} exclusive")
            all_l = sum(os.stat(p[0]).st_nlink for p in shared_inodes.values())
            det_l = sum(len(p) for p in shared_inodes.values())
            excl_l = sum(os.stat(shared_inodes[ino][0]).st_nlink for ino in excl_i)
            print(f"* Total number of links: {all_l} total, {det_l} detected, {excl_l} exclusive")
            total_s, excl_s = sum(os.stat(p[0]).st_size for p in shared_inodes.values()), sum(os.stat(shared_inodes[ino][0]).st_size for ino in excl_i)
            print(f"* Total shared size: {format_size(total_s, args.bytes_format):<5}    total, {format_size(excl_s, args.bytes_format):<5}    exclusive")

if __name__ == "__main__":
    main()
